package com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.controlller;
import java.nio.charset.StandardCharsets; import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.audit.AuditService; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.entity.AuditLog;
@RestController @RequestMapping("/api/audit") public class AuditController { @Autowired AuditService service;
 @GetMapping public List<AuditLog> all(@RequestParam(required=false) String q){return q==null?service.all():service.search(q);}
 @GetMapping("/csv") public ResponseEntity<byte[]> csv(@RequestParam(required=false) String q){List<AuditLog> logs=q==null?service.all():service.search(q); StringBuilder b=new StringBuilder("id,action,user,date_time,entity_type,entity_id,details\n"); for(AuditLog x:logs)b.append(csv(x.getId())).append(',').append(csv(x.getAction())).append(',').append(csv(x.getUserEmail())).append(',').append(csv(String.valueOf(x.getActionTime()))).append(',').append(csv(x.getEntityType())).append(',').append(csv(String.valueOf(x.getEntityId()))).append(',').append(csv(x.getDetails())).append('\n'); return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=audit-logs.csv").contentType(MediaType.parseMediaType("text/csv")).body(b.toString().getBytes(StandardCharsets.UTF_8)); }
 private String csv(Object v){String s=String.valueOf(v==null?"":v).replace("\"","\"\""); return "\""+s+"\"";}}
